def solve_tilings(grid):
    cells={(r,c) for r,row in enumerate(grid) for c,x in enumerate(row) if x==8}
    h,w=len(grid),len(grid[0]); pieces=[]
    for r in range(h-1):
      for c in range(w-1):
        sq={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
        if sq<=cells: pieces.append((sq,1,'sq'))
        for miss,color in [((r,c),2),((r,c+1),4),((r+1,c),3),((r+1,c+1),5)]:
          shape={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}-{miss}
          if shape<=cells: pieces.append((shape,color,'L'))
    sols=[]
    def rec(rem, chosen):
      if not rem:
        if sum(k=='sq' for _,_,k in chosen)==2 and sum(k=='L' for _,_,k in chosen)==3: sols.append(chosen[:])
        return
      cell=min(rem)
      for sh,col,k in pieces:
        if cell in sh and sh<=rem:
          rec(rem-sh,chosen+[(sh,col,k)])
    rec(cells,[])
    return sols
