program='''def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    pieces = []
    for r in range(h - 1):
        for c in range(w - 1):
            block = {(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)}
            if block <= cells:
                pieces.append((block, 1))
                for missing, color in (((r, c), 2), ((r, c + 1), 4), ((r + 1, c), 3)):
                    shape = block - {missing}
                    if shape <= cells:
                        pieces.append((shape, color))
    by_cell = {}
    for shape, color in pieces:
        for cell in shape:
            by_cell.setdefault(cell, []).append((shape, color))

    def cover(remaining):
        if not remaining:
            return []
        cell = min(remaining, key=lambda p: sum(shape <= remaining for shape, _ in by_cell[p]))
        for shape, color in by_cell[cell]:
            if shape <= remaining:
                rest = cover(remaining - shape)
                if rest is not None:
                    return [(shape, color)] + rest
        return None

    tiling = cover(cells)
    out = [[0] * w for _ in range(h)]
    for shape, color in tiling:
        for r, c in shape:
            out[r][c] = color
    return out
'''
